(function($){$.fn.ijaboViewer=function(options){var settings=$.extend({preview:'.image-preview',imageShape:'rectangular',allowedExtensions:['jpg','jpeg','png','gif','webp'],maxSize:2048,onInvalidType:function(message){alert(message);},onInvalidSize:function(message){alert(message);}},options);return this.each(function(){$(this).on('change',function(e){var file=e.target.files[0];if(!file)return;var ext=file.name.split('.').pop().toLowerCase();if($.inArray(ext,settings.allowedExtensions)==-1){settings.onInvalidType('Invalid file type.');$(this).val('');return;}if(file.size>settings.maxSize*1024){settings.onInvalidSize('File is too large.');$(this).val('');return;}var reader=new FileReader();reader.onload=function(e){var $preview=$(settings.preview);$preview.attr('src',e.target.result);if(settings.imageShape=='circle'){$preview.css('border-radius','50%');}else{$preview.css('border-radius','0%');}};reader.readAsDataURL(file);});});};}(jQuery));
